from functools import lru_cache

def count_ways(n):
    weights = tuple(2**i for i in range(n))

    @lru_cache(maxsize=None)
    def f(remaining, balance):
        if not remaining:
            return 1
        total = 0
        for i, w in enumerate(remaining):
            new_rem = remaining[:i] + remaining[i+1:]
            # place on left
            total += f(new_rem, balance + w)
            # place on right (if balance >= w)
            if balance >= w:
                total += f(new_rem, balance - w)
        return total

    return f(weights, 0)

for n in range(1, 9):
    print(f"n={n}: {count_ways(n)}")

